// Idempotency keys for claim submission
// build {{sim.sessionId}}
const seen = new Map<string, string>();

export function claimOnce(key: string, claimId: string): string {
  const prior = seen.get(key);
  if (prior) return prior;
  seen.set(key, claimId);
  return claimId;
}

// Duplicate submission regression test
// build {{sim.sessionId}}
import { expect, it } from 'vitest';
import { claimOnce } from '../../src/claims/idempotency';

it('rejects a duplicate submission on retry', () => {
  expect(claimOnce('k1', 'CLM-1')).toBe('CLM-1');
  expect(claimOnce('k1', 'CLM-2')).toBe('CLM-1');
});
